  "body": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>API Dashboard</title>
    <style>
        body, html {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            padding: 0;
            background-color: #f4f4f9;
            color: #333;
            line-height: 1.6;
        }

        .container {
            width: 80%;
            max-width: 1200px;
            margin: 20px auto;
            padding: 20px;
            background-color: #fff;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }

        h1 {
            color: #0056b3;
            border-bottom: 2px solid #0056b3;
            padding-bottom: 10px;
        }

        section {
            margin-top: 20px;
            padding: 20px;
            background: #ffffff;
            border: 1px solid #dddddd;
        }

        a {
            background-color: #007bff;
            color: white;
            padding: 8px 16px;
            text-decoration: none;
            border-radius: 4px;
            cursor: pointer;
        }

        a:hover {
            background-color: #0056b3;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 20px;
        }

        th, td {
            text-align: left;
            padding: 8px;
            border-bottom: 1px solid #dddddd;
        }

        th {
            background-color: #f4f4f4;
        }

        td {
            background-color: #fafafa;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>API Dashboard</h1>
        <p>The goal of this challenge is to get command execution on the flask_app container, and grab the file /FLAG.txt</p>
        <section>
            <h2>API URL</h2>
            <div>
                <p id="apiResult"></p>
                <p><a href="/api/set?url=http://flask_api:8081/script" target="_blank">reset</a></p>
            </div>
        </section>
        <section>
            <h2>Name Management</h2>
            <div>
                <p id="nameResult"></p>
                <p><a href="/name/set?name=Cocomelon" target="_blank">reset</a></p>
            </div>
        </section>
        <section>
            <h2>Hosts</h2>
            <table>
                <thead>
                    <tr>
                        <th>Name</th>
                        <th>URL</th>
                        <th>Mapping</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>Nginx Root</td>
                        <td>http://nginx:80/</td>
                        <td>http://nginx:80/</td>
                    </tr>
                    <tr>
                        <td>Flask App</td>
                        <td>http://flask_app:8080</td>
                        <td>http://nginx:80/app/</td>
                    </tr>
                    <tr>
                        <td>Flask API</td>
                        <td>http://flask_api:8081</td>
                        <td>http://nginx:8081/</td>
                    </tr>
                </tbody>
            </table>
        </section>
    </div>
    <script src="script.js"></script>
    <script>
        fetchApiData();
        fetchName();
    </script>
</body>
</html>
",
  "burp": "not routed through Burp"
}

