  "body": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Pentest Dashboard</title>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/marked@9/marked.min.js"></script>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: #0d1117;
      color: #c9d1d9;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      padding: 1.5rem 2rem;
    }

    /* ── Header ── */
    .header-row { display: flex; justify-content: space-between; align-items: center; }
    h1 { font-size: 1.2rem; color: #f0f6fc; margin-bottom: 0.25rem; }
    .header-buttons { display: flex; gap: 0.5rem; }
    .clear-btn, .tunnel-btn {
      background: none; border: 1px solid #30363d; border-radius: 4px;
      color: #6e7681; padding: 0.25rem 0.7rem; font-size: 0.75rem;
      cursor: pointer; transition: color .15s, border-color .15s;
    }
    .clear-btn:hover { color: #da3633; border-color: #da3633; }
    .tunnel-btn:hover { color: #d29922; border-color: #d29922; }

    #status { font-size: 0.8rem; color: #6e7681; margin-bottom: 0.75rem; }
    #status .dot {
      display: inline-block; width: 7px; height: 7px; border-radius: 50%;
      background: #3fb950; margin-right: 5px; animation: blink 2s infinite;
    }
    @keyframes blink { 0%,100%{opacity:1} 50%{opacity:.3} }

    /* ── Session strip ── */
    #session-strip {
      background: #161b22; border: 1px solid #30363d; border-radius: 6px;
      padding: 0.55rem 1rem; margin-bottom: 1rem;
      display: none; gap: 2rem; flex-wrap: wrap; align-items: center;
      font-size: 0.82rem;
    }
    #session-strip.visible { display: flex; }
    #session-strip .s-label { color: #6e7681; }
    #session-strip strong   { color: #f0f6fc; }
    .session-status-running       { color: #3fb950; font-weight: 700; }
    .session-status-complete      { color: #58a6ff; font-weight: 700; }
    .session-status-limit_reached { color: #ff4d4f; font-weight: 700; }

    /* ── Tab nav ── */
    .tab-nav { display: flex; gap: 0; margin-bottom: 1.25rem; border-bottom: 1px solid #30363d; }
    .tab-btn {
      background: none; border: none; border-bottom: 2px solid transparent;
      color: #8b949e; padding: 0.5rem 1.2rem; font-size: 0.85rem; cursor: pointer;
      transition: color .15s; margin-bottom: -1px;
    }
    .tab-btn:hover { color: #c9d1d9; }
    .tab-btn.active { color: #f0f6fc; border-bottom-color: #58a6ff; font-weight: 600; }
    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* ── Stats bar ── */
    #stats { display: flex; gap: 0.6rem; flex-wrap: wrap; margin-bottom: 1.25rem; }
    .stat {
      padding: 0.25rem 0.75rem; border-radius: 4px; font-size: 0.8rem;
      font-weight: 600; border: 1px solid; cursor: pointer; transition: opacity .15s;
    }
    .stat:hover { opacity: .7; }
    .stat.active { outline: 2px solid white; }
    .stat-all      { background: #21262d;              border-color: #6e7681; color: #c9d1d9; }
    .stat-critical { background: rgba(255,77,79,.15);  border-color: #ff4d4f; color: #ff4d4f; }
    .stat-high     { background: rgba(250,140,22,.15); border-color: #fa8c16; color: #fa8c16; }
    .stat-medium   { background: rgba(250,173,20,.15); border-color: #faad14; color: #faad14; }
    .stat-low      { background: rgba(82,196,26,.15);  border-color: #52c41a; color: #52c41a; }
    .stat-info     { background: rgba(24,144,255,.15); border-color: #1890ff; color: #1890ff; }

    /* ── Findings table ── */
    table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
    thead tr { background: #161b22; }
    th { text-align: left; padding: 0.5rem 0.75rem; color: #8b949e; font-weight: 500;
         border-bottom: 1px solid #30363d; }
    tbody tr { border-bottom: 1px solid #21262d; }
    tbody tr:hover { background: #161b22; }
